function validate([root, arr]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length > 0 && root[0] === null) return 'A non-empty tree must start with its root value.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 0 || v > 9))) return 'Every node value is a digit from 0 to 9.';
  let slots = root.length > 0 ? 2 : 0;
  for (let i = 1; i < root.length; i++) {
    if (slots === 0) return 'The level-order list has entries with no parent.';
    slots--;
    if (root[i] !== null) slots += 2;
  }
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 5000) return 'arr needs 1 to 5000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 9)) return 'Every value of arr is a digit from 0 to 9.';
  return null;
}

