function isValidSequence(root, arr) {
  // List every root-to-leaf path with an explicit stack and compare it as text.
  if (!root) return false;
  const target = arr.join(',');
  const stack = [[root, [root.val]]];
  while (stack.length) {
    const [node, path] = stack.pop();
    if (!node.left && !node.right) {
      if (path.join(',') === target) return true;
      continue;
    }
    for (const child of [node.left, node.right]) if (child) stack.push([child, [...path, child.val]]);
  }
  return false;
}

