function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 10);
  const top = large ? (rand() < 0.5 ? 1 : 2) : [1, 2, 9][Math.floor(rand() * 3)];
  const digit = () => Math.floor(rand() * (top + 1));
  // Large trees sometimes hang below a long chain, so the matching path is deep.
  const chain = large && rand() < 0.5 ? 200 + Math.floor(rand() * 400) : 1;
  const nodes = [{ val: digit(), left: null, right: null, parent: -1 }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: digit(), left: null, right: null, parent: i - 1 });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: digit(), left: null, right: null, parent });
    slots.push([i, 'left'], [i, 'right']);
  }
  const pathTo = i => { const p = []; for (let j = i; j !== -1; j = nodes[j].parent) p.push(nodes[j].val); return p.reverse(); };
  const leaves = [], inner = [];
  nodes.forEach((node, i) => (node.left === null && node.right === null ? leaves : inner).push(i));
  const pick = list => list[Math.floor(rand() * list.length)];
  let arr;
  const mode = Math.floor(rand() * 6);
  if (mode <= 1 || (mode === 2 && inner.length === 0)) arr = pathTo(pick(leaves));
  else if (mode === 2) arr = pathTo(pick(inner));
  else if (mode === 3) { arr = pathTo(pick(leaves)); const at = Math.floor(rand() * arr.length); arr[at] = (arr[at] + 1 + Math.floor(rand() * top)) % (top + 1); }
  else if (mode === 4) { arr = pathTo(pick(leaves)); arr.push(digit()); }
  else arr = Array.from({ length: 1 + Math.floor(rand() * (large ? 12 : 4)) }, digit);
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out, arr];
}
